        return 1;
    }
    int err_lvl = 0;
    if (a < 0) {
        err_lvl = 1;
        errno = EINVAL;
    } else if (b < 0) {
        err_lvl = 2;
        errno = ERANGE;
    } else if (c < 0) {
        err_lvl = 3;
        errno = EDOM;
    }
    if (err_lvl) {
        printf("L%d_ERROR %d\n", err_lvl, errno);
    } else {
        printf("SUCCESS %d\n", a + b + c);
    }
    return 0;
}

#include <stdio.h>
#include <errno.h>

int main(void) {
    int op, val;
    if (scanf("%d %d", &op, &val) != 2) {
        return 1;
    }
    if (op < 1 || op > 5) {
        errno = EINVAL;
        printf("OP_ERR %d\n", errno);
        return 0;
    }
    int result;
    switch (op) {
        case 1: result = 2 * val; break;
        case 2: result = 3 * val; break;
        case 3: result = val * val; break;
        case 4: result = -val; break;
        default: result = 0; break;
    }
    if (result > 1000 || result < -1000) {
        errno = ERANGE;
        printf("RANGE_ERR %d\n", errno);
    } else {
        printf("OK %d\n", result);
    }
    return 0;
}

