#include <stdio.h>
#include <errno.h>

int try_op(int op_id, int try_num) {
    int target = op_id % 4;
    if (target == 0) {
        return 0;
    }
    return (try_num >= target) ? 1 : 0;
}

int main(void) {
    int op;
    if (scanf("%d", &op) != 1) {
        return 1;
    }
    int succeeded = 0;
    int last_try = 0;
    for (int try_num = 1; try_num <= 3; try_num++) {
        last_try = try_num;
        if (try_op(op, try_num)) {
            succeeded = 1;
            break;
        }
    }
    if (succeeded) {
        printf("OK %d\n", last_try);
    } else {
        errno = EAGAIN;
        printf("FAILED %d\n", errno);
    }
    return 0;
}
